/* From Uiverse.io by mrhyddenn - Tags: card, shell */
.__UIV_SCOPE__ .container {
  width: 230px;
  height: 194px;
}

.__UIV_SCOPE__ .terminal_toolbar {
  display: flex;
  height: 30px;
  align-items: center;
  padding: 0 8px;
  box-sizing: border-box;
  border-top-left-radius: 5px;
  border-top-right-radius: 5px;
  background: linear-gradient(#504b45 0%, #3c3b37 100%);
}

.__UIV_SCOPE__ .butt {
  display: flex;
  align-items: center;
}

.__UIV_SCOPE__ .btn {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 0;
  margin-right: 5px;
  font-size: 8px;
  height: 12px;
  width: 12px;
  box-sizing: border-box;
  border: none;
  border-radius: 100%;
  background: linear-gradient(#7d7871 0%, #595953 100%);
  text-shadow: 0px 1px 0px rgba(255,255,255,0.2);
  box-shadow: 0px 0px 1px 0px #41403A, 0px 1px 1px 0px #474642;
}

.__UIV_SCOPE__ .btn-color {
  background: #ee411a;
}

.__UIV_SCOPE__ .btn:hover {
  cursor: pointer;
}

.__UIV_SCOPE__ .btn:focus {
  outline: none;
}

.__UIV_SCOPE__ .butt--exit {
  background: linear-gradient(#f37458 0%, #de4c12 100%);
}

.__UIV_SCOPE__ .user {
  color: #d5d0ce;
  margin-left: 6px;
  font-size: 14px;
  line-height: 15px;
}

.__UIV_SCOPE__ .terminal_body {
  background: rgba(56, 4, 40, 0.9);
  height: calc(100% - 30px);
  padding-top: 2px;
  margin-top: -1px;
  font-size: 12px;
  border-bottom-left-radius: 5px;
  border-bottom-right-radius: 5px;
}

.__UIV_SCOPE__ .terminal_promt {
  display: flex;
}

.__UIV_SCOPE__ .terminal_promt span {
  margin-left: 4px;
}

.__UIV_SCOPE__ .terminal_user {
  color: #7eda28;
}

.__UIV_SCOPE__ .terminal_location {
  color: #4878c0;
}

.__UIV_SCOPE__ .terminal_bling {
  color: #dddddd;
}

.__UIV_SCOPE__ .terminal_cursor {
  display: block;
  height: 14px;
  width: 5px;
  margin-left: 10px;
  animation: curbl 1200ms linear infinite;
}

@keyframes curbl {
  
  0% {
    background: #ffffff;
  }

  49% {
    background: #ffffff;
  }

  60% {
    background: transparent;
  }

  99% {
    background: transparent;
  }

  100% {
    background: #ffffff;
  }
}
